DROP VIEW "public"."recruiting_facts";--> statement-breakpoint
ALTER TABLE "enrichments" DROP CONSTRAINT "ck_enrichments_enrichmentkind";--> statement-breakpoint
ALTER TABLE "enrichments" ADD CONSTRAINT "ck_enrichments_enrichmentkind" CHECK (("kind")::text = ANY ((ARRAY['people_extraction'::character varying, 'firmographics'::character varying, 'email_scan'::character varying, 'email_pick'::character varying, 'opener'::character varying, 'video'::character varying])::text[]));--> statement-breakpoint
CREATE VIEW "public"."recruiting_facts" AS (SELECT c.id AS company_id, c.source_key, c.domain, c.name, c.country, NULLIF(round((ppp.output ->> 'jobs_reported')::numeric)::integer, 0) AS employees, NULLIF(round((ppp.output ->> 'payroll_yearly_estimate')::numeric)::bigint, 0) AS payroll_yearly_usd, substring(c.raw -> 'sba' ->> 'year_established' from '[0-9]{4}')::integer AS founded_year, op.output -> 'opener' ->> 'line' AS opener, vid.output ->> 'url' AS video_url FROM companies c LEFT JOIN LATERAL ( SELECT e.output FROM enrichments e WHERE e.company_id = c.id AND e.kind = 'firmographics' AND e.model = 'ppp-foia' ORDER BY e.prompt_version DESC, e.created_at DESC LIMIT 1 ) ppp ON true LEFT JOIN LATERAL ( SELECT e.output FROM enrichments e WHERE e.company_id = c.id AND e.kind = 'opener' AND e.output -> 'opener' ->> 'line' IS NOT NULL ORDER BY e.created_at DESC LIMIT 1 ) op ON true LEFT JOIN LATERAL ( SELECT e.output FROM enrichments e WHERE e.company_id = c.id AND e.kind = 'video' AND e.output ->> 'url' IS NOT NULL ORDER BY e.created_at DESC LIMIT 1 ) vid ON true WHERE c.niche = 'recruiting');